// 只投影本人已公开或实获条款；原遗赠上限与实际可交割资产分开，远方余额不进页面。
#include "family_inheritance_commands.hpp"
#include "resident/views/common_presentation.hpp"
#include <algorithm>
namespace hanmo::resident { namespace {
using V=BoundaryValue;
// 页码独立限制条款批次和记录数量，任何一条响应都不能导出整本遗产账。
V::Array page_of(V::Array rows,Integer page){V::Array result;for(Integer i=page*16;i<std::min<Integer>(rows.size(),page*16+16);++i)result.push_back(std::move(rows[static_cast<std::size_t>(i)]));return result;}
// 显示身份只取名字，不因已知声明泄露人物现在是否死亡、是否可行动或所在位置。
V named(const CommonStore& c,const CommonCatalog& catalog,const StableId& id){auto value=CommonPresentation(c.state(),catalog).display_name(id);return boundary::obj({{"actor_id",V{id}},{"name",V{value.ok?value.value:id}}});}
// 当前读戳供界面丢弃换人物、读档或旧世界的待确认操作。
V identity(const CommonStore& c){StableId world;const char* digits="0123456789abcdef";for(auto b:c.state().identity.world_id){world+=digits[b>>4];world+=digits[b&15];}const auto& id=c.state().identity;return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{id.execution_epoch}},{"revision",V{id.revision}},{"tick",V{id.tick}}});}
// 原批次与数量是已实际公开的知识，数量不是当前库存保证。
V::Array lots(const std::vector<SuccessionPersonalLot>& rows){V::Array result;for(const auto& row:rows)result.push_back(boundary::obj({{"lot_id",V{row.lot_id}},{"item_id",V{row.item_id}},{"quantity",V{row.quantity}}}));return result;}
}
Outcome<BoundaryValue> query_family_inheritance_page(const CommonStore& c,const CommonCatalog& common,const FamilyBequestState& grants,const FamilyDeathState& deaths,const InteractionState& meeting,const InteractionCatalog& catalog,const InteractionAccess& meetings,const FamilyInheritancePolicy& policy,const FamilyInheritanceState& state,const FamilyInheritanceAccess& access,Integer page,Integer lot_page,const StableId& notice_binding,const ActorKnownDeathReceiptRef* known_death){
 using namespace boundary;if(!policy.enabled)return {false,{},common_failure("FamilyInheritanceProfileRequired").error};if(page<0||page>255||lot_page<0||lot_page>255||notice_binding.size()>256)return {false,{},common_failure("InvalidInheritancePage").error};auto valid=validate_family_inheritance(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,access.clearance,access.sources);if(!valid.ok)return {false,{},valid.error};const auto& actor=c.state().metadata.player_actor_id;V::Array own,known,settlements;
 for(const auto& row:grants.declarations.rows()){const auto& terms=row.second.source.terms;if(terms.donor_actor_id!=actor)continue;StableId disclosure;for(const auto& d:state.disclosures.rows())if(d.second.source.declaration_id==row.first)disclosure=d.first;FamilyInheritanceCommand command;command.kind="family_bequest_disclose";command.declaration_id=row.first;auto quote=preview_family_inheritance_command(c,grants,deaths,meeting,catalog,meetings,policy,state,access,actor,command);own.push_back(obj({{"declaration_id",V{row.first}},{"beneficiary",named(c,common,terms.beneficiary_actor_id)},{"disclosure_fact_id",V{disclosure}},{"disclose_available",V{quote.ok}},{"disclose_code",V{quote.ok?StableId{}:quote.error.original.code}}}));}
 for(const auto& id:known_bequest_disclosures(state,actor)){const auto* disclosure=state.disclosures.find(id);const auto* declaration=disclosure?grants.declarations.find(disclosure->source.declaration_id):nullptr;if(!declaration)return {false,{},common_failure("InheritanceKnownSourceMissing").error};const auto& terms=declaration->source.terms;StableId acceptance;for(const auto& a:state.acceptances.rows())if(a.second.disclosure_fact_id==id)acceptance=a.first;auto original=lots(terms.lots);Integer remaining_money=0,remaining_count=0;V::Array remaining;
  if(!acceptance.empty()){auto entitlement=inheritance_personal_entitlement(c,grants,state,acceptance);if(!entitlement.ok)return {false,{},entitlement.error};remaining_money=entitlement.value.money_remaining;remaining_count=entitlement.value.remaining_lots.size();remaining=lots(entitlement.value.remaining_lots);}
  bool accept_available=false;StableId accept_code="InheritanceDeathNoticeRequired";if(!acceptance.empty())accept_code="InheritanceAlreadyAccepted";else if(policy.selected_version==2&&known_death&&access.sources){auto quote=preview_family_inheritance_acceptance_v2(c,grants,deaths,catalog,access.player,policy,state,id,*known_death,*access.sources,access.clearance);accept_available=quote.ok;accept_code=quote.ok?StableId{}:quote.error.original.code;}else if(policy.selected_version==1&&!notice_binding.empty()){auto quote=preview_family_inheritance_acceptance(c,grants,deaths,catalog,access.player,access.received_notice,policy,state,id,notice_binding,access.clearance,access.sources);accept_available=quote.ok;accept_code=quote.ok?StableId{}:quote.error.original.code;}
  known.push_back(obj({{"disclosure_fact_id",V{id}},{"declaration_id",V{disclosure->source.declaration_id}},{"donor",named(c,common,terms.donor_actor_id)},{"disclosed_tick",V{disclosure->source.tick}},{"money_limit",V{terms.money}},{"original_lot_count",V{Integer(terms.lots.size())}},{"original_lots",V{page_of(std::move(original),lot_page)}},{"acceptance_fact_id",V{acceptance}},{"accept_available",V{accept_available}},{"accept_code",V{accept_code}},{"remaining_money_limit",V{remaining_money}},{"remaining_lot_count",V{remaining_count}},{"remaining_lots",V{page_of(std::move(remaining),lot_page)}}}));
 }
 for(const auto& row:state.settlements.rows()){const auto* a=state.acceptances.find(row.second.acceptance_fact_id);if(a&&a->beneficiary_actor_id==actor)settlements.push_back(obj({{"fact_id",V{row.first}},{"acceptance_fact_id",V{row.second.acceptance_fact_id}},{"tick",V{row.second.tick}},{"money",V{row.second.transfer.money}},{"lot_count",V{Integer(row.second.transfer.lots.size())}},{"place_id",V{row.second.place_id}}}));}
 const Integer own_count=own.size(),known_count=known.size(),settlement_count=settlements.size();return {true,obj({{"actor_id",V{actor}},{"source_identity",identity(c)},{"page",V{page}},{"lot_page",V{lot_page}},{"notice_binding_fact_id",V{notice_binding}},{"own_count",V{own_count}},{"known_count",V{known_count}},{"settlement_count",V{settlement_count}},{"own_declarations",V{page_of(std::move(own),page)}},{"known_bequests",V{page_of(std::move(known),page)}},{"settlements",V{page_of(std::move(settlements),page)}},{"explanation",V{"只办理本人已获知、已接受的私人遗赠。金额与批次是原上限；交割另核当前产权、旧责任和实际同地接触。"}}}),{}};
}
}
